with grouped as (
 select model_run_id,tenant_id,cohort_month,sale_type_id,followup_definition_key,horizon_days,
 max(cohort_mature_at) as mature_at,sum(nb_cohort_membership) as nb_base,
 sum(open_contribution) as nb_open,sum(won_contribution) as nb_won,sum(lost_contribution) as nb_lost,
 sum(abandoned_contribution) as nb_abandoned,sum(unqualified_contribution) as nb_unqualified,sum(unknown_contribution) as nb_unknown
 from `dtr_sales`.`dataset_cohort_outcomes`
 where (NULL is null or team_key=NULL)
 group by model_run_id,tenant_id,cohort_month,sale_type_id,followup_definition_key,horizon_days
)
select model_run_id,tenant_id,cohort_month,sale_type_id,followup_definition_key,horizon_days,nb_base,
 if(mature_at<=parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC'),nb_won/nullIf(nb_base,0),NULL) as won_rate,
 if(mature_at<=parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC'),nb_open/nullIf(nb_base,0),NULL) as open_rate,
 if(mature_at<=parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC'),nb_lost,NULL) as nb_lost,
 if(mature_at<=parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC'),nb_abandoned,NULL) as nb_abandoned,
 if(mature_at<=parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC'),nb_unqualified,NULL) as nb_unqualified,
 if(mature_at<=parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC'),nb_unknown,NULL) as nb_unknown
from grouped

select model_run_id,event_type,sale_type_id,countIf(nb_events=1) as nb_events,
 if(countIf(is_generated_amount_calculable)=count(),sum(sum_generated_pipeline_amount),NULL) as generated_amount,
 if(countIf(is_signed_mrr_calculable)=count(),sum(sum_signed_mrr),NULL) as signed_mrr,
 if(countIf(completed_cycle_duration_days is not null)>0,quantileExactInclusiveIf(0.5)(completed_cycle_duration_days,completed_cycle_duration_days is not null),NULL) as median_observed_cycle,
 if(countIf(completed_cycle_duration_days is not null)>0,quantileExactInclusiveIf(0.9)(completed_cycle_duration_days,completed_cycle_duration_days is not null),NULL) as p90_observed_cycle
from `dtr_sales`.`dataset_sales_events`
where event_at>=parseDateTime64BestEffort('2026-09-01T00:00:00.000Z',3,'UTC')
and event_at<parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC')
group by model_run_id,event_type,sale_type_id

-- Recompute quantiles after filtering passages; entry team remains the attribution rule.
with parameters as (
 select parseDateTime64BestEffort('2026-09-30T22:00:00.000Z',3,'UTC') as observed,
 CAST(21 AS Nullable(Float64)) as threshold
), measured as (
 select d.model_run_id,d.visit_key,d.entry_team_key,d.entered_at,d.exited_at,
 d.completed_duration_days,p.threshold,
 multiIf(d.entered_at is null,'not_observable',d.entered_at>p.observed,'future',
 d.exited_at<=p.observed,'completed',d.observation_end_at<=p.observed,'not_observable','current') as population,
 if(population='current',dateDiff('millisecond',d.entered_at,p.observed)/86400000.,NULL) as current_age_days,
 if(population='current' and p.threshold is not null,current_age_days>p.threshold,NULL) as is_above_threshold,
 multiIf(current_age_days is null,NULL,current_age_days<0,NULL,current_age_days<7,'[0,7)',current_age_days<14,'[7,14)',current_age_days<30,'[14,30)','[30,+inf)') as duration_class
 from `dtr_sales`.`dataset_stage_visits` d cross join parameters p
 where (NULL is null or d.entry_team_key=NULL)
)
select model_run_id,population,count() as nb_visits,
 if(countIf(population='completed')>0,quantileExactInclusiveIf(0.5)(completed_duration_days,population='completed'),NULL) as median_completed,
 if(countIf(population='completed')>0,quantileExactInclusiveIf(0.9)(completed_duration_days,population='completed'),NULL) as p90_completed,
 if(countIf(population='current')>0,quantileExactInclusiveIf(0.5)(current_age_days,population='current'),NULL) as median_current_age,
 if(population='current' and any(threshold) is not null,countIf(is_above_threshold),NULL) as nb_above_threshold
from measured
group by model_run_id,population
